#!/bin/sh
# Fixed production purpose loader: values are data, never shell statements.
set -eu
export LC_ALL=C
fail() { echo 'control-plane configuration rejected' >&2; exit 1; }
component=${BROKERROUTER_COMPONENT:-}
case "$component" in
    control) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_HUMAN_AUDIENCE BROKERROUTER_HUMAN_ISSUER BROKERROUTER_HUMAN_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_HUMAN_AUDIENCE BROKERROUTER_HUMAN_ISSUER BROKERROUTER_HUMAN_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS";;
    assets) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_CONCURRENCY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_ASSET_S3_SESSION_TOKEN BROKERROUTER_RESULT_KEYS";;
    output-scan) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_CONCURRENCY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_ASSET_S3_SESSION_TOKEN BROKERROUTER_RESULT_KEYS";;
    output-worker) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_CONCURRENCY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_ASSET_S3_SESSION_TOKEN BROKERROUTER_RESULT_KEYS";;
    output-delivery) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_HUMAN_AUDIENCE BROKERROUTER_HUMAN_ISSUER BROKERROUTER_HUMAN_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_CONCURRENCY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_ASSET_S3_SESSION_TOKEN BROKERROUTER_HUMAN_AUDIENCE BROKERROUTER_HUMAN_ISSUER BROKERROUTER_HUMAN_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS";;
    media-api) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_PROVIDER_PRIMARY_KEY BROKERROUTER_PROVIDER_SECONDARY_KEY BROKERROUTER_RESULT_KEYS";;
    media-worker) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_PROVIDER_PRIMARY_KEY BROKERROUTER_PROVIDER_SECONDARY_KEY BROKERROUTER_RESULT_KEYS";;
    mcp-judge) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_PROVIDER_PRIMARY_KEY BROKERROUTER_PROVIDER_SECONDARY_KEY BROKERROUTER_RESULT_KEYS";;
    bff) required="BROKERROUTER_APPROVALS_AUDIENCE BROKERROUTER_BFF_ACTIVE_KEY BROKERROUTER_BFF_APPROVALS_ORIGIN BROKERROUTER_BFF_APPROVALS_SIGNING_KID BROKERROUTER_BFF_APPROVALS_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_CATALOG_ORIGIN BROKERROUTER_BFF_CATALOG_SIGNING_KID BROKERROUTER_BFF_CATALOG_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_CONSOLE_ORIGIN BROKERROUTER_BFF_KEYS BROKERROUTER_BFF_MEDIA_PREVIEW_ORIGIN BROKERROUTER_BFF_MEDIA_REVIEW_ORIGIN BROKERROUTER_BFF_MEDIA_REVIEW_SIGNING_KID BROKERROUTER_BFF_MEDIA_REVIEW_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_ORIGIN BROKERROUTER_BFF_SETTINGS_ORIGIN BROKERROUTER_BFF_SETTINGS_SIGNING_KID BROKERROUTER_BFF_SETTINGS_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_SIGNING_KID BROKERROUTER_BFF_SIGNING_PRIVATE_KEY BROKERROUTER_CATALOG_AUDIENCE BROKERROUTER_CONSOLE_AUDIENCE BROKERROUTER_MEDIA_REVIEW_AUDIENCE BROKERROUTER_OIDC_ALLOWED_ORIGINS BROKERROUTER_OIDC_CLIENT_ID BROKERROUTER_OIDC_CLIENT_SECRET BROKERROUTER_OIDC_ISSUER BROKERROUTER_SETTINGS_AUDIENCE"; allowed="BROKERROUTER_APPROVALS_AUDIENCE BROKERROUTER_BFF_ACTIVE_KEY BROKERROUTER_BFF_APPROVALS_ORIGIN BROKERROUTER_BFF_APPROVALS_SIGNING_KID BROKERROUTER_BFF_APPROVALS_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_CATALOG_ORIGIN BROKERROUTER_BFF_CATALOG_SIGNING_KID BROKERROUTER_BFF_CATALOG_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_CONSOLE_ORIGIN BROKERROUTER_BFF_KEYS BROKERROUTER_BFF_MEDIA_PREVIEW_ORIGIN BROKERROUTER_BFF_MEDIA_REVIEW_ORIGIN BROKERROUTER_BFF_MEDIA_REVIEW_SIGNING_KID BROKERROUTER_BFF_MEDIA_REVIEW_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_ORIGIN BROKERROUTER_BFF_SETTINGS_ORIGIN BROKERROUTER_BFF_SETTINGS_SIGNING_KID BROKERROUTER_BFF_SETTINGS_SIGNING_PRIVATE_KEY BROKERROUTER_BFF_SIGNING_KID BROKERROUTER_BFF_SIGNING_PRIVATE_KEY BROKERROUTER_CATALOG_AUDIENCE BROKERROUTER_CONSOLE_AUDIENCE BROKERROUTER_MEDIA_REVIEW_AUDIENCE BROKERROUTER_OIDC_ALLOWED_ORIGINS BROKERROUTER_OIDC_CLIENT_ID BROKERROUTER_OIDC_CLIENT_SECRET BROKERROUTER_OIDC_ISSUER BROKERROUTER_SETTINGS_AUDIENCE";;
    console) required="BROKERROUTER_CONSOLE_AUDIENCE BROKERROUTER_CONSOLE_ISSUER BROKERROUTER_CONSOLE_PUBLIC_KEYS"; allowed="BROKERROUTER_CONSOLE_AUDIENCE BROKERROUTER_CONSOLE_ISSUER BROKERROUTER_CONSOLE_PUBLIC_KEYS";;
    catalog) required="BROKERROUTER_CATALOG_AUDIENCE BROKERROUTER_CATALOG_ISSUER BROKERROUTER_CATALOG_PUBLIC_KEYS"; allowed="BROKERROUTER_CATALOG_AUDIENCE BROKERROUTER_CATALOG_CONNECTIONS BROKERROUTER_CATALOG_ISSUER BROKERROUTER_CATALOG_PUBLIC_KEYS";;
    settings) required="BROKERROUTER_SETTINGS_AUDIENCE BROKERROUTER_SETTINGS_ISSUER BROKERROUTER_SETTINGS_PUBLIC_KEYS"; allowed="BROKERROUTER_SETTINGS_AUDIENCE BROKERROUTER_SETTINGS_ISSUER BROKERROUTER_SETTINGS_PUBLIC_KEYS";;
    approvals) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_APPROVALS_AUDIENCE BROKERROUTER_APPROVALS_ISSUER BROKERROUTER_APPROVALS_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_APPROVALS_AUDIENCE BROKERROUTER_APPROVALS_ISSUER BROKERROUTER_APPROVALS_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS";;
    media-review) required="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_MEDIA_REVIEW_AUDIENCE BROKERROUTER_MEDIA_REVIEW_ISSUER BROKERROUTER_MEDIA_REVIEW_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS"; allowed="BROKERROUTER_ACTIVE_RESULT_KEY BROKERROUTER_ASSET_CONCURRENCY BROKERROUTER_ASSET_S3_ACCESS_KEY_ID BROKERROUTER_ASSET_S3_BUCKET BROKERROUTER_ASSET_S3_ENDPOINT BROKERROUTER_ASSET_S3_REGION BROKERROUTER_ASSET_S3_SECRET_ACCESS_KEY BROKERROUTER_ASSET_S3_SESSION_TOKEN BROKERROUTER_MEDIA_REVIEW_AUDIENCE BROKERROUTER_MEDIA_REVIEW_ISSUER BROKERROUTER_MEDIA_REVIEW_PUBLIC_KEYS BROKERROUTER_RESULT_KEYS";;
    *) fail;;
esac
purpose_file=/run/secrets/purpose_env
config_file=/run/secrets/component_config
for file in "$purpose_file" "$config_file"; do
    [ -f "$file" ] && [ ! -L "$file" ] && [ -r "$file" ] || fail
    [ "$(wc -c < "$file")" -le 1048576 ] || fail
done
# Exact generator grammar, including the per-service LOGIN, TLS host and CA.
login=$(printf '%s' "$component" | tr '-' '_')
[ "$(wc -l < "$purpose_file")" -eq 1 ] || fail
line=$(cat "$purpose_file")
printf '%s\n' "$line" | grep -Eq "^DATABASE_URL='postgres://brokerrouter_${login}_login:[0-9a-f]{64}@postgres:5432/brokerrouter[?]sslmode=verify-full&sslrootcert=/run/secrets/pg_ca'$" || fail
DATABASE_URL=${line#DATABASE_URL=\'}
DATABASE_URL=${DATABASE_URL%\'}
export DATABASE_URL
umask 077
scratch=$(mktemp -d /tmp/brokerrouter-config.XXXXXXXX) || fail
trap 'rm -rf "$scratch"' EXIT HUP INT TERM
seen=''
while IFS= read -r line || [ -n "$line" ]; do
    [ "${#line}" -le 131072 ] || fail
    name=${line%%=*}
    encoded=${line#*=}
    [ "$name" != "$line" ] || fail
    case " $allowed " in *" $name "*) ;; *) fail;; esac
    case " $seen " in *" $name "*) fail;; esac
    [ -n "$encoded" ] || fail
    printf '%s' "$encoded" | grep -Eq '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' || fail
    printf '%s' "$encoded" | base64 -d > "$scratch/value" 2>/dev/null || fail
    canonical=$(base64 < "$scratch/value" | tr -d '\n')
    [ "$canonical" = "$encoded" ] || fail
    # Command substitution cannot preserve NUL; reject it before reading the value.
    if od -An -v -t x1 "$scratch/value" | tr ' ' '\n' | grep -qx 00; then fail; fi
    iconv -f UTF-8 -t UTF-8 "$scratch/value" > /dev/null 2>&1 || fail
    [ -s "$scratch/value" ] || fail
    value=$(cat "$scratch/value"; printf '.')
    value=${value%.}
    export "$name=$value"
    seen="$seen $name"
done < "$config_file"
for name in $required; do
    case " $seen " in *" $name "*) ;; *) fail;; esac
done
rm -rf "$scratch"
trap - EXIT HUP INT TERM
# The existing managed entrypoint still owns UID/GID dropping. It gets no file to source.
unset BROKERROUTER_ENV_FILE BROKERROUTER_COMPONENT
exec /usr/local/bin/container-entrypoint "$@"
